const fs = require('fs');
const handler = fs.readFileSync('handler.js','utf8');
const rowsData = JSON.parse(fs.readFileSync('rows.json','utf8'));

function makeDoc() {
  const rows = rowsData.map(cells => ({
    cells: cells.map(text => ({ textContent: text })),
    style: {},
  }));
  const table = { tBodies: [{ rows }] };
  const noMatch = { style: {} };
  return {
    rows, noMatch,
    document: {
      getElementById(id) {
        if (id === 'retained-contacts') return table;
        if (id === 'contact-search-no-match') return noMatch;
        return null;
      },
    },
  };
}

function run(query, withTable = true) {
  const env = makeDoc();
  const input = { value: query };
  const doc = env.document;
  if (!withTable) {
    const orig = doc.getElementById.bind(doc);
    doc.getElementById = id => id === 'retained-contacts' ? null : orig(id);
  }
  const fn = new Function('document', handler);
  fn.call(input, doc);
  return {
    visible: env.rows.map(r => r.style.display !== 'none'),
    noMatchShown: env.noMatch.style.display !== 'none',
  };
}

const cases = [
  ['', true, [true,true,true], false],
  ['a@', true, [true,true,false], false],
  ['丙', true, [false,false,true], false],
  ['c@', true, [false,false,false], true],
  ['A@', true, [false,false,false], true],   // case-sensitive
  [' a@', true, [false,false,false], true],  // leading space not trimmed
  ['example.invalid', true, [true,true,true], false],
  ['', false, [], false],      // zero retained: typing not tested here
  ['x', false, [], false],     // zero retained + nonempty query: message stays hidden
];
let ok = true;
for (const [q, wt, exp, expMsg] of cases) {
  const r = run(q, wt);
  const pass = JSON.stringify(r.visible) === JSON.stringify(exp) && r.noMatchShown === expMsg;
  if (!pass) ok = false;
  console.log(pass?'PASS':'FAIL', JSON.stringify(q), '->', JSON.stringify(r.visible), 'msg=', r.noMatchShown);
}
process.exit(ok?0:1);
