def __init__(self):
    super().__init__(convert_charrefs=True)
    self.search_input_attrs = None
    self.handler = None
    self.paragraphs = []  # (id, style, text)
    self.table_ids = []
    # 当前表格的单元格文本序列（先保留表后排除表，与文档顺序一致）。
    self.table_cells = []
    self._table_index = -1
    self._row_cells = None
    self._cell = None
    self._p = None

def handle_starttag(self, tag, attrs):
    attrs_dict = dict(attrs)
    if tag == "input" and attrs_dict.get("id") == SEARCH_INPUT_ID:
        self.search_input_attrs = attrs_dict
        # 属性值已由解析器按实体规则解码，即浏览器中的处理函数原文。
        self.handler = attrs_dict.get("oninput")
    elif tag == "p":
        self._p = [attrs_dict.get("id"),
                   attrs_dict.get("style"), []]
    elif tag == "table":
        self.table_ids.append(attrs_dict.get("id"))
        self.table_cells.append([])
        self._table_index += 1
    elif tag == "tr" and self._table_index >= 0:
        self._row_cells = []
    elif tag == "td" and self._row_cells is not None:
        self._cell = []

def handle_data(self, data):
    if self._cell is not None:
        self._cell.append(data)
    if self._p is not None:
        self._p[2].append(data)

def handle_endtag(self, tag):
    if tag == "td" and self._cell is not None:
        self._row_cells.append("".join(self._cell))
        self._cell = None
    elif tag == "tr" and self._row_cells is not None:
        self.table_cells[self._table_index].extend(self._row_cells)
        self._row_cells = None
    elif tag == "p" and self._p is not None:
        self.paragraphs.append(
            (self._p[0], self._p[1], "".join(self._p[2]))
        )
        self._p = None

def rows(self, table_index=0):
    """把第 table_index 个表格的扁平单元格按三列一组转成记录行。"""
    cells = self.table_cells[table_index]
    return [cells[i:i + 3] for i in range(0, len(cells), 3)]

